// Factor III — config lives in the environment, never in the jar.
//   The SAME jar runs in dev, staging, prod by pointing at different env vars.
@ConfigurationProperties("payments")
public record PaymentProps(String gatewayUrl, int timeoutMs) {}

@RestController
public class PaymentController {
    private final PaymentProps props;
    PaymentController(PaymentProps props) { this.props = props; }   // injected, not hardcoded

    @PostMapping("/charge")
    public void charge(@RequestBody Charge c) {
        // Factor IV — the gateway is an attached backing service (URL/env).
        // Factor IX — this instance holds NO session state, so the platform
        //   can kill it, replace it, or scale to 10 replicas any time.
        client.post(props.gatewayUrl()).body(c).exchange();
    }
}
// Factor XI — logs go to stdout as a stream; the platform routes them to
//   Loki/CloudWatch. We never write to a local file (it dies with the pod).
//   Disposable: graceful shutdown on SIGTERM finishes in-flight requests
//   before the platform reaps the container.
